file.diff:
--- a/styles/main.css
+++ b/styles/main.css
@@ -1,6 +1,10 @@
+:root { --bg: #fdf8ef; --ink: #1f2a24; }
+[data-theme="dark"] { --bg: #14181a; --ink: #f2efe6; }
 body {
-  background: #fdf8ef;
-  color: #1f2a24;
+  background: var(--bg);
+  color: var(--ink);
 }

--- /dev/null
+++ b/src/theme.js
@@ -0,0 +1,8 @@
+export function toggleTheme() {
+  const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
+  document.documentElement.dataset.theme = next;
+  return next;
+}

--- a/src/storage.js
+++ b/src/storage.js
@@ -10,3 +10,9 @@
+export const saveTheme = (t) => localStorage.setItem('theme', t);
+export const loadTheme = () => localStorage.getItem('theme');

fixFile.diff:
--- a/src/app.js
+++ b/src/app.js
@@ -3,3 +3,5 @@
-const t = loadTheme() ?? 'light';
+const t = loadTheme() || 'light';
+document.documentElement.dataset.theme = t;

